<?php

declare(strict_types=1);

namespace App\Service\DocumentGenerator\Report\Section\Appendix;

use App\Service\DocumentGenerator\DocStyleRegistry;
use App\Service\DocumentGenerator\Report\ReportContext;
use App\Service\DocumentGenerator\Report\SectionBuilderInterface;
use PhpOffice\PhpWord\Element\Section;

/**
 * Приложение «Классификация терминов».
 */
final class TermsClassificationAppendix implements SectionBuilderInterface
{
    private const TERMS = [
        'Обследование' => 'комплекс мероприятий по определению и оценке фактических значений контролируемых параметров, характеризующих эксплуатационное состояние, пригодность и работоспособность объектов обследования и определяющих возможность их дальнейшей эксплуатации или необходимость восстановления или усиления.',
        'Дефект' => 'отдельное несоответствие конструкций какому-либо параметру, установленному проектом или нормативным документом (СП, ГОСТ, ТУ, СН и т.д.).',
        'Повреждение' => 'неисправность, полученная конструкцией при изготовлении, транспортировании, монтаже или эксплуатации.',
        'Поверочный расчёт' => 'расчёт существующих конструкций по действующим нормам проектирования с введением в расчёт полученных в результате обследования или по проектной и исполнительной документации геометрических параметров конструкций, фактической прочности строительных материалов, действующих нагрузок, уточнённой расчётной схемы с учётом имеющихся дефектов и повреждений.',
        'Категория технического состояния' => 'степень эксплуатационной пригодности строительной конструкции или здания и сооружения в целом, установленная в зависимости от доли снижения несущей способности и эксплуатационных характеристик конструкций.',
        'Оценка технического состояния' => 'установление степени повреждения и категории технического состояния строительных конструкций или зданий и сооружений в целом на основе сопоставления фактических значений количественно оцениваемых признаков со значениями этих же признаков, установленных проектом или нормативным документом.',
        'Нормативный уровень технического состояния' => 'категория технического состояния, при котором количественное и качественное значение параметров всех критериев оценки технического состояния строительных конструкций зданий и сооружений соответствуют требованиям нормативных документов (СП, ТСН, ГОСТ, ТУ и т.д.).',
        'Исправное состояние' => 'категория технического состояния строительной конструкции или здания и сооружения в целом, характеризующаяся отсутствием дефектов и повреждений, влияющих на снижение несущей способности и эксплуатационной пригодности.',
        'Работоспособное состояние' => 'категория технического состояния, при которой некоторые из численно оцениваемых контролируемых параметров не отвечают требованиям проекта, норм и стандартов, но имеющиеся нарушения требований не приводят к нарушению работоспособности, и несущая способность конструкций с учётом влияния имеющихся дефектов и повреждений обеспечивается.',
        'Ограниченно работоспособное состояние' => 'категория технического состояния конструкций, при которой имеются дефекты и повреждения, приведшие к некоторому снижению несущей способности, но отсутствует опасность внезапного разрушения, и функционирование конструкции возможно при контроле её состояния, продолжительности и условий эксплуатации.',
        'Недопустимое состояние' => 'категория технического состояния строительной конструкции или здания и сооружения в целом, характеризующаяся снижением несущей способности и эксплуатационных характеристик, при котором существует опасность для пребывания людей и сохранности оборудования (необходимо проведение страховочных мероприятий и усиление конструкций).',
        'Аварийное состояние' => 'категория технического состояния строительной конструкции или здания и сооружения в целом, характеризующаяся повреждениями и деформациями, свидетельствующими об исчерпании несущей способности и опасности обрушения (необходимо проведение срочных противоаварийных мероприятий).',
        'Степень повреждения' => 'установленная в процентном отношении доля потери проектной несущей способности строительной конструкцией.',
        'Несущие конструкции' => 'строительные конструкции, воспринимающие эксплуатационные нагрузки и воздействия и обеспечивающие пространственную устойчивость здания.',
        'Усиление' => 'комплекс мероприятий, обеспечивающих повышение несущей способности и эксплуатационных свойств строительной конструкции или здания и сооружения в целом по сравнению с фактическим состоянием или проектными показателями.',
    ];

    public function build(Section $section, ReportContext $context): void
    {
        $bodyBold = DocStyleRegistry::bodyTextBold();
        $body     = DocStyleRegistry::bodyText();
        $para     = DocStyleRegistry::paragraphIndent();

        foreach (self::TERMS as $term => $definition) {
            $textRun = $section->addTextRun($para);
            $textRun->addText($term . ' ', $bodyBold);
            $textRun->addText('— ' . $definition, $body);
        }
    }
}
